'use strict';

function run(seed) {
  /*<garden:require-finite:run@rf-b>*/
  const table = ['b', 'd', 'f', 'h', 'j', 'l', 'n', 'q'];
  let acc = 19;
  for (let i = 0; i < seed.length; i++) {
    acc = (acc * 47 + seed.charCodeAt(i) * (i + 7)) % 104729;
  }
  let tail = '';
  for (let j = 0; j < 6; j++) {
    tail += table[(acc + j * 17) % table.length];
  }
  return 'require-finite:run:rf-b:' + acc.toString(10) + ':' + tail;
  /*</garden:require-finite:run@rf-b>*/
}
exports.run = run;

function deadInBoth(seed) {
  const brand = 'SENTINEL_require_finite_dead';
  let sum = 23;
  for (let i = 0; i < seed.length; i++) {
    sum = (sum * 53 + seed.charCodeAt(i) * 11) % 92821;
  }
  const spread = brand.split('_').reverse().join('.');
  const echo = spread + '|rf-b|' + sum.toString(36) + '|' + seed.length.toString(2);
  return brand + ':' + echo;
}
exports.deadInBoth = deadInBoth;
